import type { LocationSearchResult, LocationValue, MarkerImageOption } from "./types"

function pointNumber(value: number | (() => number) | undefined): number | undefined {
  if (typeof value === "function") return Number(value())
  if (typeof value === "number") return Number(value)
  return undefined
}

export function locationValue(value: unknown): LocationValue | null {
  return value && typeof value === "object"
    ? ({ ...(value as Record<string, any>) } as LocationValue)
    : null
}

export function locationAddressLabel(value: unknown): string {
  const location = locationValue(value)
  if (!location) return ""

  const address = location.address
  const formatted =
    address && (address.formatted || address.address_formatted || address.formatted_address)

  if (typeof formatted === "string" && formatted) return formatted
  if (location.geoPoint) {
    return `${location.geoPoint.lat},${location.geoPoint.lng}`
  }
  if (location.svgPoint) {
    return `${location.svgPoint.x},${location.svgPoint.y}`
  }
  return ""
}

export function locationFromSearchResult(
  result: LocationSearchResult,
  markerPath: string,
): LocationValue | null {
  const lat = pointNumber(result.geometry?.location?.lat)
  const lng = pointNumber(result.geometry?.location?.lng)
  if (lat == null || lng == null || Number.isNaN(lat) || Number.isNaN(lng)) {
    return null
  }

  const address: Record<string, string> = {
    formatted: result.formatted_address,
  }
  ;(result.address_components ?? []).forEach((item) => {
    const type = item.types?.[0]
    if (!type) return
    address[type] = item.long_name
    if (item.short_name && item.short_name !== item.long_name) {
      address[`${type}_short`] = item.short_name
    }
  })

  return {
    address,
    geoPoint: { lat, lng },
    img: markerPath,
    imagePath: markerPath,
    markerImagePath: markerPath,
  }
}

export function locationFromCoordinateQuery(
  query: string,
  markerPath: string,
): LocationValue | null {
  const match = query.trim().match(/^([-+]?(?:\d+(?:\.\d+)?)),\s*([-+]?(?:\d+(?:\.\d+)?))$/)
  if (!match) return null

  const lat = Number(match[1])
  const lng = Number(match[2])
  if (Number.isNaN(lat) || Number.isNaN(lng) || lat < -90 || lat > 90 || lng < -180 || lng > 180) {
    return null
  }

  const formatted = `${lat},${lng}`
  return {
    address: { formatted },
    geoPoint: { lat, lng },
    img: markerPath,
    imagePath: markerPath,
    markerImagePath: markerPath,
  }
}

export function withMarkerPath(value: unknown, markerPath: string): LocationValue | null {
  const location = locationValue(value)
  if (!location) return null
  return {
    ...location,
    img: markerPath,
    imagePath: markerPath,
    markerImagePath: markerPath,
  }
}

export function markerPath(value: unknown, fallback = ""): string {
  const location = locationValue(value)
  const current = location?.markerImagePath || location?.imagePath || location?.img
  return typeof current === "string" && current ? current : fallback
}

export function markerOptionPath(option: MarkerImageOption): string {
  return option.relativeUrl || option.url || ""
}
