import { resourceApiUrl } from "@/lib/resource-api-url"
import { adminRestFetch } from "@/lib/admin-rest-fetch"
import { getAdminParams } from "@/lib/admin-params"
import { loadGoogleMapsApiOnce } from "@/lib/google-maps-loader"
import type {
  LocationFieldAdapter,
  LocationSearchResult,
  LocationValue,
  MarkerImageOption,
} from "./types"

type MapSvgLocationAdapterOptions = {
  markerDefaults?: LocationFieldAdapter["markerDefaults"]
  runtimeClient?: any
  markerImages?: MarkerImageOption[]
  filterableFields?: string[]
}

type StandaloneLocationAdapterOptions = {
  markerDefaults?: LocationFieldAdapter["markerDefaults"]
  picker?: LocationFieldAdapter["picker"]
  markerImages?: MarkerImageOption[]
}

async function browserGeocodeRequest(
  query: string,
  language?: string,
): Promise<LocationSearchResult[] | null> {
  const google = (window as any).google
  if (!google?.maps?.Geocoder) {
    return null
  }

  const geocoder = new google.maps.Geocoder()
  return await new Promise<LocationSearchResult[]>((resolve, reject) => {
    geocoder.geocode(
      {
        address: query,
        ...(language ? { language } : {}),
      },
      (results: LocationSearchResult[] | null, status: string) => {
        if (status === "OK") {
          resolve(Array.isArray(results) ? results : [])
          return
        }
        if (status === "ZERO_RESULTS") {
          resolve([])
          return
        }
        reject(new Error(`Google geocoding failed: ${status}`))
      },
    )
  })
}

async function serverGeocodeRequest(
  query: string,
  language?: string,
): Promise<LocationSearchResult[]> {
  const params = getAdminParams()
  const url = resourceApiUrl(params.apiUrl, "/geocoding")
  const search = new URLSearchParams({
    address: query,
    ...(language ? { language } : {}),
  })
  const response = await fetch(url + (url.includes("?") ? "&" : "?") + search.toString(), {
    credentials: "same-origin",
    headers: {
      Accept: "application/json",
      "X-WP-Nonce": params.nonce,
    },
  })

  if (!response.ok) {
    throw new Error(`MapSVG geocoding failed: ${response.status}`)
  }

  const body = (await response.json()) as {
    results?: LocationSearchResult[]
    error_message?: string
  }
  if (body.error_message) {
    throw new Error(body.error_message)
  }
  return Array.isArray(body.results) ? body.results : []
}

async function geocodeRequest(query: string, language?: string): Promise<LocationSearchResult[]> {
  const browserResults = await browserGeocodeRequest(query, language)
  if (browserResults !== null) {
    return browserResults
  }
  return await serverGeocodeRequest(query, language)
}

async function standaloneGeocodeRequest(
  query: string,
  language?: string,
): Promise<LocationSearchResult[]> {
  try {
    await loadGoogleMapsApiOnce()
    const browserResults = await browserGeocodeRequest(query, language)
    if (browserResults !== null) {
      return browserResults
    }
  } catch {
    // Keep the global Database usable when the Maps JS key is missing or blocked.
  }
  return await serverGeocodeRequest(query, language)
}

export async function uploadMarker(file: File): Promise<MarkerImageOption> {
  const params = getAdminParams()
  const url = resourceApiUrl(params.apiUrl, "/markers")
  const data = new FormData()
  data.append("file", file)
  const response = await adminRestFetch(url, {
    method: "POST",
    credentials: "same-origin",
    headers: { "X-WP-Nonce": params.nonce },
    body: data,
  })
  if (!response.ok) {
    throw new Error(`Marker upload failed: ${response.status}`)
  }
  const body = (await response.json()) as {
    marker?: MarkerImageOption
    error?: string
  }
  if (body.error || !body.marker) {
    throw new Error(body.error || "Marker upload returned no marker.")
  }
  // Keep newly uploaded images available when a preference change rebuilds an adapter.
  const bootstrap = window.mapsvgReactAdminParams
  if (bootstrap) {
    const catalog = bootstrap.markerImages ?? (bootstrap.markerImages = [])
    if (!catalog.some(item => item.relativeUrl === body.marker!.relativeUrl)) catalog.push({ name: file.name, relativeUrl: body.marker.relativeUrl, pathShort: body.marker.relativeUrl })
  }
  return body.marker
}
function updateRuntimeLocation(location: any, value: LocationValue): void {
  if (value.img || value.imagePath || value.markerImagePath) {
    location.setImage?.(value.img || value.markerImagePath || value.imagePath)
  }
  if (value.address) location.setAddress?.(value.address)
  if (value.geoPoint) location.setGeoPoint?.(value.geoPoint)
  if (value.svgPoint) location.setSvgPoint?.(value.svgPoint)
}

export function createStandaloneLocationAdapter(
  options: StandaloneLocationAdapterOptions = {},
): LocationFieldAdapter {
  const markers = [...(options.markerImages ?? [])]

  return {
    isGeo: true,
    markerDefaults: options.markerDefaults,
    picker: options.picker,
    hasMapInteraction: Boolean(options.picker),
    search: standaloneGeocodeRequest,
    markerImages: () => [...markers],
    async uploadMarker(file) {
      const marker = await uploadMarker(file)
      markers.push(marker)
      return marker
    },
    async getMarkerFields() {
      return []
    },
    async getMarkerFieldOptions() {
      return []
    },
    bind() {
      return () => undefined
    },
    sync() {
      // Standalone database editing has no map runtime to synchronize.
    },
  }
}

export function createMapSvgLocationAdapter(
  map: any,
  options: MapSvgLocationAdapterOptions = {},
): LocationFieldAdapter {
  const markers = [...(options.markerImages ?? [])]
  let listener: ((value: LocationValue | null) => void) | undefined
  let binding: object | undefined
  let watchedMarker: any
  let markerChangeHandler: (() => void) | undefined

  const stopWatching = () => {
    if (watchedMarker?.events && markerChangeHandler) {
      watchedMarker.events.off("change", markerChangeHandler)
    }
    watchedMarker = undefined
    markerChangeHandler = undefined
  }

  const watchMarker = (marker: any) => {
    stopWatching()
    if (!marker?.events || !marker.location) return

    watchedMarker = marker
    const owner = binding
    markerChangeHandler = () => {
      if (!owner || binding !== owner || marker.isMoving?.()) return
      listener?.(marker.location?.getData?.() ?? null)
    }
    marker.events.on("change", markerChangeHandler)
  }

  const bindMapPick = (owner: object) => {
    map.setMarkerEditHandler?.((location: any) => {
      if (binding !== owner) return
      const marker = location?.marker
      if (marker) {
        map.setEditingMarker?.(marker)
        if (options.markerDefaults?.image) location.setImage?.(options.markerDefaults.image)
        marker.setImage?.()
        watchMarker(marker)
      }
      listener?.(location?.getData?.() ?? null)
    })

    const current = map.getEditingMarker?.()
    if (current) watchMarker(current)
  }

  return {
    isGeo: Boolean(map.isGeo?.()),
    markerDefaults: options.markerDefaults,
    hasMapInteraction: true,
    search: geocodeRequest,
    markerImages: () => [...markers],
    async uploadMarker(file) {
      const marker = await uploadMarker(file)
      markers.push(marker)
      return marker
    },
    setDefaultMarkerPath(path) {
      map.setDefaultMarkerImage?.(path)
    },
    async getMarkerFields() {
      return [...(options.filterableFields ?? [])]
    },
    async getMarkerFieldOptions(fieldName) {
      if (!fieldName || !map.objectsRepository?.getOptionsByField) {
        return []
      }
      const normalized = fieldName.startsWith("Object.")
        ? fieldName.slice("Object.".length)
        : fieldName
      const result = await Promise.resolve(map.objectsRepository.getOptionsByField(normalized))
      return Array.isArray(result)
        ? result.map((option: any) => ({
            label: String(option.label ?? option.value ?? ""),
            value: option.value,
          }))
        : []
    },
    bind(onChange) {
      const owner = {}
      binding = owner
      listener = onChange
      bindMapPick(owner)

      return () => {
        if (binding !== owner) return
        binding = undefined
        listener = undefined
        stopWatching()
        map.setMarkerEditHandler?.(null)
        map.unsetEditingMarker?.()
      }
    },
    sync(value) {
      const currentMarker = map.getEditingMarker?.()

      if (!value) {
        if (currentMarker) {
          map.markerDelete?.(currentMarker)
        }
        map.unsetEditingMarker?.()
        stopWatching()
        return
      }

      if (currentMarker?.location) {
        updateRuntimeLocation(currentMarker.location, value)
        currentMarker.setImage?.()
        watchMarker(currentMarker)
        return
      }

      const client = options.runtimeClient ?? (window as any).mapsvg
      if (!client?.location || !client?.marker) {
        return
      }

      const location = new client.location(value)
      const marker = new client.marker({ location, mapsvg: map })
      map.setEditingMarker?.(marker)
      watchMarker(marker)
    },
  }
}
