import { getAdminParams } from "@/lib/admin-params"
import type { MapsvgClient } from "@/lib/mapsvg-client"
import { initializeAdminFrame } from "@/lib/admin-frame"

/** Load the runtime in its own realm; constructors borrowed from the parent use the wrong window. */
export async function loadPreviewFrame(iframe: HTMLIFrameElement, signal: AbortSignal): Promise<MapsvgClient> {
  const scripts = getAdminParams().previewScripts
  if (!scripts?.length || !window.mapsvgFrontendParams) throw new Error("Preview runtime configuration is unavailable. Reload the editor.")
  const timeout = window.setTimeout(() => abort(new Error("The preview runtime took too long to load.")), 30000)
  let rejectPending: ((reason: unknown) => void) | undefined
  const cleanups: (() => void)[] = []
  let stopped: unknown
  function abort(reason: unknown) { stopped = reason; rejectPending?.(reason) }
  const onAbort = () => abort(signal.reason ?? new DOMException("Preview closed", "AbortError"))
  signal.addEventListener("abort", onAbort, { once: true })
  function bounded<T>(start: (resolve: (value: T) => void, reject: (reason: unknown) => void) => void): Promise<T> {
    if (signal.aborted) onAbort()
    if (stopped) return Promise.reject(stopped)
    return new Promise<T>((resolve, reject) => {
      rejectPending = reject
      start(resolve, reject)
    })
  }
  try {
    await bounded<void>((resolve) => { initializeAdminFrame(iframe); resolve() })
    const frame = iframe.contentWindow
    const doc = iframe.contentDocument
    if (!frame || !doc) throw new Error("The preview frame is unavailable.")
    doc.documentElement.style.height = "auto"
    doc.body.style.cssText = "margin:0;min-height:100vh;height:auto;display:flex;flex-direction:column;padding:16px;box-sizing:border-box;background:#fff"
    frame.mapsvgFrontendParams = JSON.parse(JSON.stringify(window.mapsvgFrontendParams))
    // The nonce can be renewed while this iframe stays alive.
    Object.defineProperty(frame, "mapsvgReactAdminParams", { configurable: true, get: () => window.mapsvgReactAdminParams })
    const inline = (code: string) => {
      const tag = doc.createElement("script")
      tag.textContent = code
      doc.head.append(tag)
    }
    for (const asset of scripts) {
      for (const code of asset.before) inline(code)
      await bounded<void>((resolve, reject) => {
        const script = doc.createElement("script")
        script.src = asset.src
        script.type = asset.type
        script.onload = () => resolve()
        script.onerror = () => reject(new Error(`Could not load preview asset: ${asset.src}`))
        doc.head.append(script)
      })
      for (const code of asset.after) inline(code)
    }
    if (!frame.mapsvg?.map) {
      await bounded<void>((resolve) => {
        const initialized = () => resolve()
        frame.addEventListener("mapsvgClientInitialized", initialized, { once: true })
        cleanups.push(() => frame.removeEventListener("mapsvgClientInitialized", initialized))
      })
    }
    if (!frame.mapsvg?.map) throw new Error("The preview runtime did not initialize.")
    return frame.mapsvg
  } finally {
    window.clearTimeout(timeout)
    signal.removeEventListener("abort", onAbort)
    for (const cleanup of cleanups) cleanup()
  }
}
